INSERT INTO `mydb`.`DISEASE` (`disease_id`, `disease_name`, `plant_pathogen`, `symptoms`) VALUES (1, 'Apple Scab', 'Venturia inaequalis', 'A serious disease of apples and ornamental crabapples, apple scab attacks both leaves and fruit. The fungal disease forms pale yellow or olive-green spots on the upper surface of leaves. Dark, velvety spots may appear on the lower surface. Severely infected leaves become twisted and puckered and may drop early in the summer. Symptoms on fruit are similar to those found on leaves. Scabby spots are sunken and tan and may have velvety spores in the center. As these spots mature, they become larger and turn brown and corky. Infected fruit becomes distorted and may crack allowing entry of secondary organisms. Severely affected fruit may drop, especially when young.');
INSERT INTO `mydb`.`DISEASE` (`disease_id`, `disease_name`, `plant_pathogen`, `symptoms`) VALUES (2, 'Apple Black Rot', 'Botryosphaeria obtusa', 'Black rot is a disease of apples that infects fruit, leaves and bark. It can also jump to healthy tissue on pear or quince trees, but is typically a secondary fungus of weak or dead tissues in other plants. Early symptoms are often limited to leaf symptoms such as purple spots on upper leaf surfaces. As these spots age, the margins remain purple, but the centers dry out and turn yellow to brown. Over time, the spots expand and heavily infected leaves drop from the tree. Infected branches or limbs will show characteristic red-brown sunken areas that expand each year.');
INSERT INTO `mydb`.`DISEASE` (`disease_id`, `disease_name`, `plant_pathogen`, `symptoms`) VALUES (3, 'Apple Cedar Rust', 'Gymnosporangium juniperi-virginianae', 'Cedar apple rust is a fungal disease that requires juniper plants to complete its complicated two-year life-cycle. Spores overwinter as a reddish-brown gall on young twigs of various juniper species. In early spring, during wet weather, these galls swell and bright orange masses of spores are blown by the wind where they infect susceptible apple and crab-apple trees. The spores that develop on these trees will only infect junipers the following year. From year to year, the disease must pass from junipers to apples to junipers again; it cannot spread between apple trees. On apple and crab-apple trees, look for pale yellow pinhead-sized spots on the upper surface of the leaves shortly after bloom. These gradually enlarge to bright orange-yellow spots which make the disease easy to identify. Orange spots may develop on the fruit as well. Heavily infected leaves may drop prematurely.');
INSERT INTO `mydb`.`DISEASE` (`disease_id`, `disease_name`, `plant_pathogen`, `symptoms`) VALUES (4, 'Cherry Powdery Mildew', 'Podosphaera clandestina', 'Initial symptoms, often occurring 7 to 10 days after the onset of the first irrigation, are light roughly-circular, powdery looking patches on young, susceptible leaves (newly unfolded, and light green expanding leaves). Older leaves develop an age-related (ontogenic) resistance to powdery mildew and are naturally more resistant to infection than younger leaves. Look for early leaf infections on root suckers, the interior of the canopy, or the crotch of the tree where humidity is high. In contrast to other fungi, powdery mildews do not need free water to germinate but germination and fungal growth are favored by high humidity. The disease is more likely to initiate on the undersides (abaxial) of leaves but will occur on both sides at later stages. As the season progresses and infection is spread by wind, leaves may become distorted, curling upward. Severe infections may cause leaves to pucker and twist. Newly developed leaves on new shoots become progressively smaller, are often pale, and may be distorted.');
INSERT INTO `mydb`.`DISEASE` (`disease_id`, `disease_name`, `plant_pathogen`, `symptoms`) VALUES (5, 'Corn Gray Leaf Spot', 'Cercospora zeae-maydis', 'Gray leaf spot (GLS) is a common fungal disease in corn. Gray leaf spot lesions begin as small necrotic pinpoints with chlorotic halos, these are more visible when leaves are backlit. Coloration of initial lesions can range from tan to brown before sporulation begins. Because early lesions are ambiguous, they are easily confused with other foliar diseases such as anthracnose leaf blight, eyespot, or common rust. As infection progresses, lesions begin to take on a more distinct shape. Lesion expansion is limited by parallel leaf veins, resulting in the blocky shaped “spots”. As sporulation commences, the lesions take on a more gray coloration. Entire leaves can be killed when weather conditions are favorable, and rapid disease progression causes lesions to merge.');
INSERT INTO `mydb`.`DISEASE` (`disease_id`, `disease_name`, `plant_pathogen`, `symptoms`) VALUES (6, 'Corn Common Rust', 'Puccinia sorghi', 'Spreads by windblown spores from southern corn-growing areas. Lesions begin as flecks on leaves that develop into small tan spots. Spots turn into elongated brick-red to cinnamon-brown pustules with jagged appearance. Found on both upper AND lower leaf surfaces (unlike southern rust). Pustules turn dark brown to black late in the season. Occurs on a leaf only, NOT on sheaths, stalks, ear shanks, and husk leaves.');
INSERT INTO `mydb`.`DISEASE` (`disease_id`, `disease_name`, `plant_pathogen`, `symptoms`) VALUES (7, 'Corn Northern Leaf Blight', 'Exserohilum turcicum', 'Northern corn leaf blight is a foliar disease of corn (maize). The most common diagnostic symptom of the disease on corn is cigar-shaped or elliptical necrotic gray-green lesions on the leaves that range from one to seven inches long. These lesions may first appear as narrow, tan streaks that run parallel to the leaf veins. Fully developed lesions typically have a sooty appearance during humid weather, as a result of spore (conidia) formation. As the disease progresses, the lesions grow together and create large areas of dead leaf tissue. The lesions found in Northern corn leaf blight are more acute if the leaves above the ear are infected during or soon after the flowering of the plant. In highly resistant hybrids, the only visible disease symptoms may be minute yellow spots. On severely infected plants, lesions can become so numerous that the leaves are eventually destroyed. Late in the season, plants may look like they have been killed by an early frost.');
INSERT INTO `mydb`.`DISEASE` (`disease_id`, `disease_name`, `plant_pathogen`, `symptoms`) VALUES (8, 'Grape Black Rot', 'Guignardia bidwellii', 'Grape black rot originated in eastern North America, but now occurs in portions of Europe, South America, and Asia. Relatively small, brown circular lesions develop on infected leaves and within a few days tiny black spherical fruiting bodies (pycnidia) protrude from them. Elongated black lesions on the petiole may eventually girdle these organs, causing the affected leaves to wilt. Shoot infection results in large black elliptical lesions. These lesions may contribute to breakage of shoots by wind, or in severe cases, may girdle and kill young shoots altogether. This fungus bides its time. Most plants show very little signs of infection until its too late. They will look very healthy until fruit sets. Even flowering will be normal. Infection of the fruit is the most serious phase of the disease and may result in substantial economic loss. Infected berries first appear light or chocolate brown; it will have a spot that looks very round, like the eye of a bird. That spot will get larger and infect more of the fruit bunch and more of the plant. This creates masses of black pycnidia developing on the surface. Finally, infected berries shrivel and turn into hard black raisin-like bodies that are called mummies.');
INSERT INTO `mydb`.`DISEASE` (`disease_id`, `disease_name`, `plant_pathogen`, `symptoms`) VALUES (9, 'Grape Esca (Black Measles)', 'Phaeoacremonium aleophilum, Phaeomoniella chlamydospora', 'The foliar symptom of Esca is an interveinal striping. The stripes, which start out as dark red in red cultivars and yellow in white cultivars, dry and become necrotic. Foliar symptoms may occur at any time during the growing season, but are most prevalent during July and August. They are often restricted to an individual shoot or to shoots originating from the same spur or cane. Symptomatic leaves can dry completely and drop prematurely. On berries, small, round, dark spots each bordered by a brown-purple ring, may occur. These fruit spots, which are better viewed on white cultivars, may appear at any time between fruit set and ripening. In severely affected vines, the berries often crack and dry or are subject to spoilage. Symptomatic fruit is found only on shoots with symptomatic leaves, but you can find shoots with symptomatic leaves and no symptomatic fruit. Cross-sectional cuts through canes, spurs, cordons, or trunks from which symptomatic shoots originate will reveal concentric rings of dark spots. Eventually the spur or cane from which symptomatic shoots originate may die. The appearance of foliar and especially fruit symptoms is inconsistent from year to year, which is thought to be due to possibly climate-induced variability in toxin production by the pathogen. A severe form of Esca known as apoplexy, which is more common in Europe, results in a sudden dieback of the entire shoot or adjacent shoots, rather than a gradual development of foliar symptoms.');
INSERT INTO `mydb`.`DISEASE` (`disease_id`, `disease_name`, `plant_pathogen`, `symptoms`) VALUES (10, 'Grape Leaf Blight (Isariopsis Leaf Spot)', 'Pseudocercospora vitis', 'On leaf surface we will see lesions which are irregularly shaped (2 to 25 mm in diameter). Initially lesions are dull red to brown in color turn black later. If disease is severe this lesions may coalesce. On berries we can see symptom similar to black rot but the entire clusters will collapse. Common in tropical and subtropical grapes. The disease appear late in the season. Cynthiana and Cabernet Sauvignon are susceptible to this pathogen.');
INSERT INTO `mydb`.`DISEASE` (`disease_id`, `disease_name`, `plant_pathogen`, `symptoms`) VALUES (11, 'Orange Citrus Greening disease (Haunglongbing)', 'Candidatus Liberibacter spp', 'Haunglongbing (HLB) is distinguished by the common symptoms of yellowing of the veins and adjacent tissues; followed by splotchy mottling of the entire leaf, premature defoliation, dieback of twigs, decay of feeder rootlets and lateral roots, and decline in vigor, ultimately followed by the death of the entire plant. Affected trees have stunted growth, bear multiple off-season flowers (most of which fall off), and produce small, irregularly shaped fruit with a thick, pale peel that remains green at the bottom and tastes very bitter. Common symptoms can often be mistaken for nutrient deficiencies; however, the distinguishing factor between nutrient deficiencies is the pattern of symmetry. Nutrient deficiencies tend to be symmetrical along the leaf vein margin, while HLB has an asymmetrical yellowing around the vein. The most noticeable symptom of HLB is greening and stunting of the fruit, especially after ripening. After initial transmission in the shoots, the Huanglongbing pathogen infects roots. This infection causes rapid fibrous root loss of up to 40 percent before symptoms appear in the canopy. Studies show that roots infected with Phytophthora spp. may interact with the bacterial infection in roots, compounding root damage and loss. ');
INSERT INTO `mydb`.`DISEASE` (`disease_id`, `disease_name`, `plant_pathogen`, `symptoms`) VALUES (12, 'Peach Bacterial Spot', 'Xanthomonas', 'Bacterial leaf spot of peach, also known as bacterial shot hole, is a common disease on older peach trees and nectarines. The most characteristic sign of peach tree leaf spot are angular purple to purple-brown spots on foliage, followed by the center of lesion falling out, giving the leaves a “shot hole” appearance. Leaves soon turn yellow and drop. Fruit has small water-soaked markings that enlarge and merge to eventually cover large areas. Cracking or pitting occurs along the lesions as the fruit grows, enabling brown rot fungus to infiltrate the fruit. Bacterial leaf spot also affects current season growth.');
INSERT INTO `mydb`.`DISEASE` (`disease_id`, `disease_name`, `plant_pathogen`, `symptoms`) VALUES (13, 'Peper,bell Bacterial Spot', 'Xanthomonas', 'Except for virus diseases, bacterial spot is the most important disease affecting peppers all over the world. The same bacterial disease affects tomato. Necrotic spots may appear on leaves, stems, and fruits. Leaf symptoms appear first on the undersides of leaves as small water-soaked areas. These spots enlarge up to 1/4 inch in diameter, turn dark brown, and are slightly raised. On the upper leaf surface the spots are depressed with a brown border around a beige center. Several lesions may coalesce, resulting in large necrotic areas, and large numbers of lesions can occur on leaf margins and tips where moisture accumulates. Eventually the leaves yellow and drop off, increasing the chance for sunscald. Spots on fruits become raised, scablike areas that make the product unmarketable.');
INSERT INTO `mydb`.`DISEASE` (`disease_id`, `disease_name`, `plant_pathogen`, `symptoms`) VALUES (14, 'Potato Early Blight', 'Alternaria solani', 'It is found wherever potatoes are grown. The disease primarily affects leaves and stems, but under favorable weather conditions, and if left uncontrolled, can result in considerable defoliation and enhance the chance for tuber infection. Premature defoliation may lead to considerable reduction in yield. The disease can also be severe on tomatoes, and can occur on other solanaceous crops and weeds.');
INSERT INTO `mydb`.`DISEASE` (`disease_id`, `disease_name`, `plant_pathogen`, `symptoms`) VALUES (15, 'Potato Late Blight', 'Phytophthora infestans', 'The first symptoms of late blight in the field are small, light to dark green, circular to irregular-shaped water-soaked spots. These lesions usually appear first on the lower leaves. Lesions often begin to develop near the leaf tips or edges, where dew is retained the longest. During cool, moist weather, these lesions expand rapidly into large, dark brown or black lesions, often appearing greasy (Figure 2). Leaf lesions also frequently are surrounded by a yellow chlorotic halo. The lesions are not limited by leaf veins, and as new infections occur and existing infections coalesce, entire leaves can become blighted and killed within just a few days. The lesions also may be present on petioles and stems of the plant. During active growth, especially in cool, wet weather, a white mildew-appearing area is visible at the edge of the lesions or along petioles (Figure 6). This is the area where the late blight pathogen actively is producing spores. As the weather changes to warm and dry, these lesions become dry, stop sporulating and become tan.');
INSERT INTO `mydb`.`DISEASE` (`disease_id`, `disease_name`, `plant_pathogen`, `symptoms`) VALUES (16, 'Squash Powdery Mildew', 'Podosphaera xanthii, Erysiphe cichoracearum', 'White deposits develop on the top sides of leaves that make them look like they have been dusted with flour. As this fungal disease advances, leaves become grayish-green and become dry to the touch. Eventually these leaves turn brown and fall off. Powdery mildew is most likely to infect older plants that are beginning to decline after producing a crop. ');
INSERT INTO `mydb`.`DISEASE` (`disease_id`, `disease_name`, `plant_pathogen`, `symptoms`) VALUES (17, 'Strawberry Leaf Scorch', 'Diplocarpon earliana', 'Symptoms of leaf scorch consist of numerous small, irregular, purplish spots or “blotches” that develop on the upper surface of leaves. The centers of the blotches become brownish. Blotches may coalesce until they nearly cover the leaflet, which then appears purplish to reddish to brown. The fungus overwinters on infected leaves. The fungus produces spore-forming structures in the spring on both surfaces of dead leaves. These structures produce spores abundantly in midsummer. In the presence of free water, these spores can germinate and infect the plant within 24 hours. Older and middle-aged leaves are infected more easily than young ones.');
INSERT INTO `mydb`.`DISEASE` (`disease_id`, `disease_name`, `plant_pathogen`, `symptoms`) VALUES (18, 'Tomato Bacterial spot', 'Xanthomonas', 'On tomato, leaf lesions are initially circular and water-soaked and may be surrounded by a faint yellow halo. In general, spots are dark brown to black and circular on leaves and stems. Spots rarely develop to more than 3 mm in diameter. Lesions can coalesce causing a blighted appearance of leaves and a general yellowing may occur on leaves with multiple lesions. Infected pepper leaves drop prematurely; this exposes fruit to the sun and results in sun scalding. Fruit lesions begin as small, slightly raised blisters, which become dark brown, scab-like, and can appear slightly raised as they increase in size.');
INSERT INTO `mydb`.`DISEASE` (`disease_id`, `disease_name`, `plant_pathogen`, `symptoms`) VALUES (19, 'Tomato Early Blight', 'Alternaria sp.', 'Early blight can affect seedlings but is generally observed on older plants and is especially severe on plants of poor vigor. Plants infected with the fungus can display collar rust on the stems, infected older leaves, and fruits that crack at the stem. Infection on leaves is the most common symptom. The appearance of circular or irregular dark spots on the lower, more mature leaves is one of the first symptoms of infection. Eventually, the spots enlarge into a series of concentric rings surrounded by a yellow area. The entire leaf may be killed and will drop off the plant. Early blight can result in extensive defoliation, exposing fruit to sunscald and reducing yields. This disease typically progresses from the base of the plant, upward.');
INSERT INTO `mydb`.`DISEASE` (`disease_id`, `disease_name`, `plant_pathogen`, `symptoms`) VALUES (20, 'Tomato Late Blight', 'Phytophthora infestans', 'True to its name, the disease occurs later in the growing season with symptoms often not appearing until after blossom. Late blight first appears on the lower, older leaves as water-soaked, gray-green spots. As the disease matures, these spots darken and a white fungal growth forms on the undersides. Eventually the entire plant will become infected. Crops can be severely damaged. Unlike other fungal diseases, this plant problem does not overwinter in the soil or on garden trash. Instead infected tubers, transplants or seeds introduce the spores. Wind will also carry the disease from nearby gardens. ');
INSERT INTO `mydb`.`DISEASE` (`disease_id`, `disease_name`, `plant_pathogen`, `symptoms`) VALUES (21, 'Tomato Leaf Mold', 'Cladosporium fulvum', 'The tomato leaf mold fungus is a specific pathogen of tomato plant Lycopersicon, this pathogen has restricted host range (host-specific pathogen) that only infects tomatoes, mainly in greenhouses. The symptoms of this disease commonly occur on foliage, and it develops on both sides of the leaf on the adaxial and abaxial surface. The older leaves are infected first and then the disease moves up towards young leaves. Symptoms of tomato leaf mold appear usually with foliage, but fruit infection is rare. The primary symptom appears on the upper surface of infected leaves as a small spot pale green or yellowish with indefinite margins, and on the corresponding area of the lower surface, the fungus begins to sporulate.The diagnostic symptom develops on the lower surface as an olive green to grayish purple and velvety appearance, which are composed of spores (conidia). Continuously, the color of the infected leaf changes to yellowish-brown and the leaf begins to curl and dry. The leaves will drop upon reaching a premature stage, and the defoliation of the infected host will cause further infection. This disease develops well in relative humidity levels above 85%. When the temperature reaches an optimum level for germinating, the host will be infected by the pathogen. Occasionally, this pathogen causes disease on the fruit or blossoms with various symptoms. Fruits such as green and ripe one will develop dark rot on the stem. The blossoms will be killed before fruits grow.');
INSERT INTO `mydb`.`DISEASE` (`disease_id`, `disease_name`, `plant_pathogen`, `symptoms`) VALUES (22, 'Tomato Septoria Leaf Spot', 'Septoria lycopersici', 'It is one of the most destructive diseases of tomato foliage and is particularly severe in areas where wet, humid weather persists for extended periods. Septoria leaf spot usually appears on the lower leaves after the first fruit sets. Spots are circular, about 1/16 to 1/4 inch in diameter with dark brown margins and tan to gray centers with small black fruiting structures. Characteristically, there are many spots per leaf. This disease spreads upwards from oldest to youngest growth. If leaf lesions are numerous, the leaves turn slightly yellow, then brown, and then wither. Fruit infection is rare.');
INSERT INTO `mydb`.`DISEASE` (`disease_id`, `disease_name`, `plant_pathogen`, `symptoms`) VALUES (23, 'Tomato Two-spotted Spider Mite', 'Tetranychus urticae', 'Two-spotted spider mites are occasional pests that can cause serious damage to some vegetable crops during hot dry weather. Mites can injure tomatoes, beans, muskmelons, watermelons, and sweet corn. Extended periods of hot, dry weather favors mite buildups. Infestations usually first occur at the edge of a field, typically near rank weed growth or dirt roads. Feeding injury often gives the top leaf surfaces a mottled or speckled, dull appearance. Leaves then turn yellow and drop. Large populations produce visible webbing that can completely cover the leaves. In the field, spider mites are favored by hot dry weather, which also aggravates injury by stressing the plant. Damage is often underestimated since the wounds and the pest are not apparent to our eyes without close inspection. Leaves become blotched with pale yellow, reddish brown spots ranging from small to large areas on both upper and lower leaf surfaces. Other symptoms caused by either severe or constant attack include distorted leaves, overall loss of plant vigor (in spite of adequate moisture and nutrition), whitening or spotting of leaves, yellowing of the plant or some of the leaves, and in some cases loss of foliage and death');
INSERT INTO `mydb`.`DISEASE` (`disease_id`, `disease_name`, `plant_pathogen`, `symptoms`) VALUES (24, 'Tomato Target Spot', 'Corynespora cassiicola', 'The disease starts on the older leaves and spreads upwards. The first signs are irregular-shaped spots (less than 1 mm) with a yellow margin. Some of the spots enlarge up to 10 mm and show characteristics rings, hence the name of \"target spot\". Spread to all leaflets and to other leaves is rapid (Photo 3), causing the leaves to turn yellow, collapse, and die. Spots also occur on the stems. They are long and thin. Small light brown spots with dark margins may also occur on the fruit. The spores are spread by wind-blown rain, and if windy wet weather continues for a few days, the spread is fast and plants lose their leaves quickly. The source of the fungus is from other crops, the remains of the previous crop, and, perhaps, other host species. The fungus is very common on papaya leaves causing angular, light brown or grey spots, 2 mm diameter, sometimes surrounded by a yellow margin; the centers of the spots often fall out producing a \"shot-hole\" effect. It is also a disease of cucumber.');
INSERT INTO `mydb`.`DISEASE` (`disease_id`, `disease_name`, `plant_pathogen`, `symptoms`) VALUES (25, 'Tomato Yellow Leaf Curl Virus', 'Tomato yellow leaf curl virus', 'Tomato yellow leaf curl virus (TYLCV), a disease that threatens both commercial tomato production fields and home gardens, was identified in March 2007 by Dr. Robert Gilbertson, University of California, Davis (UCD), in greenhouse tomato samples from Brawley, Calif. Typical symptoms for this disease in tomato are yellow (chlorotic) leaf edges, upward leaf cupping, leaf mottling, reduced leaf size, and flower drop. TYLCV can have a severe impact on tomato production. Plants infected at an early stage won\'t bear fruit and their growth will be severely stunted. TYLCV identification based only on symptomatology is unreliable, because similar symptoms can be caused by other viruses or various growing conditions.');
INSERT INTO `mydb`.`DISEASE` (`disease_id`, `disease_name`, `plant_pathogen`, `symptoms`) VALUES (26, 'Tomato Mosaic virus', 'Tomato mosaic virus', 'The foliage of affected tomato plants shows mottling, with alternating yellowish and darker green areas, the latter often appearing thicker and raised giving a blister-like appearance. The leaves tend to be fern-like in appearance with pointed tips and younger leaves may be twisted. The fruit may be distorted, yellow blotches and necrotic spots may occur on both ripe and green fruit and there may be internal browning of the fruit wall. In young plants, the infection reduces the set of fruit and may cause distortions and blemishes. The entire plant may be dwarfed and the flowers discolored. Environmental conditions influence the symptoms. These include temperature, day length, and light intensity as well as the variety, the age of the plant at infection and the virulence of the strain of Tomato mosaic virus.');
