INSERT INTO `mydb`.`CLASS` (`class_id`, `class_name`, `alias_class_name`, `DISEASE_disease_id`) VALUES (35, 'Tomato___Tomato_Yellow_Leaf_Curl_Virus', 'Tomato Yellow Leaf Curl Virus', 25);
INSERT INTO `mydb`.`CLASS` (`class_id`, `class_name`, `alias_class_name`, `DISEASE_disease_id`) VALUES (36, 'Tomato___Tomato_mosaic_virus', 'Tomato Mosaic Virus', 26);
INSERT INTO `mydb`.`CLASS` (`class_id`, `class_name`, `alias_class_name`, `DISEASE_disease_id`) VALUES (37, 'Tomato___healthy', 'Tomato healthy', NULL);
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (1, 'Liquid Copper', 'Bonide', 'Approved for organic gardening. Bonide Liquid Copper Fungicide controls a large variety of plant diseases including peach leaf curl, powdery mildew, black spot, rust, anthracnose, fire blight and bacterial leaf spot. Use on vegetables, roses, fruits and turf. Can be used up to the day of harvest.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (2, 'Sulfur Plant Fungicide', 'Bonide', 'Bonide Sulfur Plant Fungicide is a finely ground wettable powder containing 90% elemental sulfur. Controls diseases on fruits, vegetables and flowers. Effective against powdery mildew, rust, scab, brown rot, rose black spot and many more. Works on pest mites, too! Will not burn plants.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (3, 'Plant Doctor', 'Organocide', 'Organocide Plant Doctor is a broad-spectrum systemic fungicide that moves throughout the entire plant to prevent and treat diseases, as listed (see Product Label below). Effective against a large number of plant problems including those that cause root rot, leaf and stem blights, leaf spots and more!');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (4, 'Orchard Spray', 'Bonide', 'Non-toxic solutions for orchards have been difficult to locate — until now. Bonide Orchard Spray is a safe, one-hit concentrate for common insect attacks and fungal problems. Small-scale gardeners will find it a great value because it’s also formulated for use on vegetables, ornamental plants, houseplants and even lawns!');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (5, 'Serenade Garden', 'AgraQuest', 'A broad spectrum biofungicide, Serenade Garden contains a patented strain of Bacillus subtilis. Provides protection against many of the most common fungal and bacterial garden diseases (see label). Now you can grow beautiful disease-free fruits, vegetables and flowers – without chemicals that can be harmful to people or the environment. It is so safe you can confidently harvest and eat fruits and vegetables the very same day they are treated. Will NOT harm bees or beneficial insects.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (6, 'Monterey Bi-Carb Old Fashioned Fungicide', 'Monterey', 'Potassium bicarbonate soluble powder for control of powdery mildew on roses, vegetables, grapes, fruit trees and ornamentals. A more acidic nutrient solution will neutralise bicarbonates on its own. This in turn reduces the amount of acid needed to control the pH in the reservoir and thus reduces the possibility of acute phosphate accumulation.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (7, 'Eagle® 20 EW', 'DowAgroSciences', 'Eagle® 20EW specialty fungicide is a systemic, protectant and curative fungicide for the control of the diseases listed on this label in established turfgrass (including residential and commercial lawns, ornamental turfgrass, grounds or lawns around business and offlce complexes, and golf course fairways, roughs, tee boxes, and greens), landscape ornamentals, greenhouse and nursery ornamentals, and non-commercial tree fruits and vines, speciflcally apples, stone fruits and grapes. Optimum disease control is achieved when this product is applied in a regularly scheduled preventive program.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (8, 'JMS Stylet Oil', 'JMS', 'It will kill powdery mildew on contact as well as prevent development of mildew for 10 to 14 days, depending on the usage rate. JMS Stylet Oil acts as a smotherant and prevents insect respiration and spore germination. Use JMS Stylet Oil to kill mites, scale, whiteflies, psyllids and leafhoppers. This year-round spray oil is OMRI listed and WSDA registered; it can be used in greenhouses, on field crops, or on fruit trees.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (9, 'Headline EC', 'BASF', 'Headline fungicide is a fast-acting, broad-spectrum fungicide that delivers a high level of activity on more than 50 major diseases that can threaten yield and crop quality. Headline fungicide helps prevent diseases and provides protection for more than 90 crops, including corn, soybeans and wheat.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (10, 'Proline 480 SC', 'BayerCropScience', 'PROLINE 480 SC Foliar Fungicide is a broad-spectrum systemic fungicide for the control or suppression of listed Ascomycetes, Basidiomycetes and Deuteromycetes diseases on barley, bushberries, borage, Brassica carinata, canola, chickpeas, crambe, low growing berries - except strawberries, corn, cucurbits, flax (linseed), lentils, oats, Oriental mustard, peanut, rapeseed, safflower, soybean, sugar beet, sunflower, wheat and certain other small grains.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (11, 'Bumper 418 EC', 'ADAMA', 'BUMPER is a broad-spectrum systemic fungicide that protects against yield and quality losses due to leaf disease. BUMPER is registered for application at both the early season herbicide timing and flag leaf timing in wheat and barley.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (12, 'Aproach ®', 'DuPont ™', 'DuPont™ Aproach® fungicide delivers better protection from production-limiting plant diseases in corn, soybeans, cereals, dry beans and canola. From enhanced in-season protection to improved harvestable yield, Aproach® delivers results growers will see. Provides effective plant disease control of foliar and soil-borne diseases, including gray leaf spot, northern corn leaf blight, Southern leaf blight and common rust in corn; soybean white mold, frogeye leaf spot, brown spot and Asian soybean rust in soybeans; and powdery mildew, rusts, tan spot, septoria leaf blotch and glume blotch in wheat.  On fields with heavy disease pressure and for intensively managed acres with high yield potential, consider using DuPont™ Aproach® Prima fungicide.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (13, 'PropiMax® EC', 'DowAgroSciences', 'PropiMax® EC fungicide is a broad-spectrum fungicide for the control of certain diseases in crops.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (14, 'SOVRAN®', 'BASF', 'The active ingredient in SOVRAN fungicide belongs to a new class of fungicides, the strobilurins. Strobilurins are synthetic derivatives of a natural antifungal substance. SOVRAN fungicide has a new mode of action and is effective against pathogens resistant to other fungicides. SOVRAN fungicide has a protective effect because it inhibits spore germination and a curative-eradicative effect due to the inhibition of mycelial growth and sporulation of the fungus on the leaf surface. SOVRAN fungicide can therefore be applied in either preor post-infection situations. However, optimum disease control is achieved when SOVRAN fungicide is applied in a regularly scheduled protective spray program and is used in rotation program with other fungicides. On apples and pears, SOVRAN fungicide controls apple/pear scab and powdery mildew. On grapes, SOVRAN fungicide controls powdery mildew, downy mildew and black rot.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (15, 'Pristine®', 'BASF', 'Pristine fungicide is the leading fungicide used in specialty crops for the control of a wide spectrum of diseases as well as increased plant/fruit health. Pristine features a combination of the active ingredients, pyraclostrobin (the active ingredient in Headline® fungicide) and boscalid to provide disease control in a variety of crops. Use higher rates for control of anthracnose, black rot and downy mildew in grapes. During periods of rapid growth or high disease pressure, use the higher rate.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (16, 'Sodium Arsenite Solution', 'Titripur® Reag. USP', 'Sodium arsenite is an inoganic sodium salt with formula with formula NaAsO2. It has a role as an insecticide, an antibacterial agent, a herbicide, a rodenticide, a carcinogenic agent, an antineoplastic agent and an antifungal agent. It is an arsenic molecular entity and an inorganic sodium salt. Molecular Formula: NaAsO₂ or AsNaO₂');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (17, 'Ridomil Gold® SL', 'Syngenta', 'Due to hyper-systemic uptake and translocation properties, Ridomil Gold® SL protects vegetables, citrus, potatoes and tree nuts from soilborne oomycete diseases. Ridomil Gold SL also improves stand, root health and crop vigor and has flexible application methods and a clear, easy-to-use formulation. Ridomil Gold has direct fungicidal activity against Phytophthora root rot disease. Roots rapidly absorb the fungicide, which is then translocated throughout the root system, promoting root health, crop development and enhancing your chance to grow more citrus.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (18, 'Aliette™', 'Bayer CropScience', 'The crop protection experts are aiming to make orange trees more resistant to the disease with the tried-and-proven Bayer active substance fosetyl-aluminum. This is the active component of the fungicide Aliette™, which is used to treat apples, pears and grapevines.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (19, 'FireLine™ 17WP', 'AgroSource, Inc', 'FireLine 17 is a superior formulation recommended for management of Fire Blight in Apples or Pears, Bacterial Spot in Peaches and Nectarines, and Citrus Greening (HLB) in Citrus. FireLine 17 is specifically recommended for management of Fire Blight in apple and pear orchards where resistance to streptomycin may be present. FireLine 17 is a free-flowing, dry, wettable powder designed for ease of application with commercial sprayer equipment. In addition, FireLine 17 has an unsurpassed stability profile.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (20, 'KOCIDE 3000-O', 'KOCIDE LLC', 'KOCIDE 3000-O is the most technologically advanced copper fungicide in the market. It delivers the maximum concentration of biologically active copper ions while preserving plant safety. Its patented BioActive™ technology enables lower metallic copper use rates, an environmental plus, all without compromising excellent disease protection. It is an outstanding dry flowable formulation for easy handling, mixing and use in fruiting vegetable crops. Increased bioactivity. Excellent dispersion. Long residual. It all adds up to make Kocide 3000-O the best copper fungicide your money can buy.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (21, 'KOCIDE 2000-O', 'KOCIDE LLC', 'Kocide 2000-O copper hydroxide bactericide/fungicide is used to control a wide range of diseases in citrus, tree fruit and many other crops. Kocide 2000-O provides an excellent foundation for disease control when applied as a protectant. Kocide 2000-O’s optimum particle size and proprietary formulation provides outstanding coverage and excellent rainfastness. Kocide 2000-O, proven by growers across the globe provides consistent performance and a high level of crop safety. Kocide 2000-O is easy to use and is compatible with most fungicides, insecticides, and foliar nutrients.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (22, 'Endura®', 'BASF', 'Endura fungicide features the active ingredient boscalid, which offers growers a unique mode of action with superior disease control in many important crops. Endura fungicide offers growers a unique mode of action with superior control of white mold and foliar diseases, including early blight and suppression of gray mold. It is a preventive fungicide that inhibits new growth of fungal cells while also blocking the energy production in existing cells. Endura fungicide is an effective and reliable product for the protection and control of a wide variety of diseases, because its site of action is different from strobulirins and most other fungicides. It also works extremely well in fungicide-resistance management rotations.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (23, 'Equus® 720 SST', 'Makhteshim Agan of North America, Inc.', 'Equus® 720 SST is a flowable product containing chlorothalonil to be used as a spray for the control of many important plant diseases.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (24, 'Nu-Cop® 50DF', 'Agri Star ™', 'Nu-Cop® 50DF controls melanose, blight, greasy spot and many other fungus, mold and disease.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (26, 'Agri-Mek® SC', 'Syngenta', 'Agri-Mek® SC provides growers with powerful, fast acting protection against a range of damaging mites and insects. Agri-Mek SC contains the Group 6 insecticide abamectin, and provides a modern, water-based formulation that is absorbed within the plant leaf to provide extended residual control and protection. Agri-Mek SC also offers the convenience of flexible timing and application methods when pests pose a threat.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (27, 'Acramite 50WS Miticide', 'Chemtura', 'Acramite 50WS Miticide versatile spider mite protection on specialty crops. This innovative product attacks spider mites at all stages, delivering peace of mind all season long. Active Ingredient: Bifenazate 50.0%');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (28, 'Oberon® SC 240', 'BayerCropScience', 'Oberon®, a non-systemic foliar insecticide / acaricide belongs to a chemical class developed by Bayer: ketoenols. Due to this innovative “ketoenol technology,” Oberon provides a new mode of action for whitefly and spider mite (Tetranychus) control, and shows no cross-resistance to current acaricides and insecticides. Oberon has a high level of long-lasting efficacy. Yet, with its excellent environmental profile and friendliness to Beneficial’s and pollinators, Oberon fits with IPM programs.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (29, 'Insecticidal Soap', 'Safer', 'Safer Brand Insecticidal Soap is made from naturally occurring plant oils and animal fats. Penetrates the protective outer shell of soft bodied insect pests and causes dehydration and death within hours. OMRI Listed for use in organic production. Insecticidal Soap can be used inside or out to kill aphids, mealybugs, spider mites, whiteflies and more. Does NOT kill beneficial insects, such as ladybugs and praying mantis and leaves behind NO chemical residues. MAY BE USED UP TO THE DAY OF HARVEST.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (30, 'Bon-Neem II', 'Bonide', 'A water based blend of potassium soaps, Bonide Bon-Neem is derived from Indian neem tree seed oil. Specially formulated to kill mites, aphids, whitefly and other insects on contact. Ideal for use on houseplants, herbs, vegetables, fruits, flowers, trees, lawns and shrubs.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (31, 'Platinum®', 'Syngenta', 'With a wide variety of soil application methods, Platinum® insecticide offers residual control of sucking and chewing insects in vegetables, potatoes and fruit. Its highly systemic activity results in rapid root uptake and long residual control.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (32, 'Admire® Pro', 'BayerCropScience', 'Admire® Pro Systemic Protectant is a soil- and foliar-applied systemic insecticide that provides economical and enduring control of damaging insects in a variety of fruit and vegetable crops. Consistently delivering outstanding control of many sucking and chewing pests, Admire Pro was developed for today’s farming operations. The improved, highly concentrated formulation is easy to mix, use and apply.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (33, 'Captan fungicide', 'Southern Agricultural Insecticides, Inc.', 'A fungicide for plant disease control. Not for use on plants being grown for sale or other commercial use, or for commercial seed production, or for research purposes. For use on plants intended for aesthetic purposes or climatic modifications and being grown in interior landscapes, ornamental gardens or parks, or on lawns and grounds.');
INSERT INTO `mydb`.`DRUG` (`drug_id`, `drug_name`, `pharma_company_name`, `drug_description`) VALUES (34, 'TOPSIN® M 70WP', 'Cerexagri-Nisso LLC', 'A fungicide for plant disease control. Apply Topsin M 70WP with ground or aerial equipment, using sufficient volume of spray to provide thorough coverage. Add required amount of Topsin M 70WP to partially filled tank agitated by mechanical or hydraulic means, and then add remaining required amount of water.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (1, 1, 'Mix 0.5 to 2.0 oz. Liquid Copper per gallon of water. For best results, start spraying before the disease is visible or when it is first noticed on the plant. Spray all plant parts thoroughly, and repeat every 7-10 days. If possible, time applications so that at least 12 hours of dry weather follows application. Will NOT burn plants.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (2, 1, 'Dust over plants or mix 3 Tbsp Sulfur Plant Fungicide per gallon of water. Repeat applications at 10-14 day intervals or as necessary, up to day of harvest. Applications must be timed to go on before rainy or spore discharge periods.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (3, 1, 'Apply as a soil drench or foliar spray (3-4 tsp/ gallon of water) to prevent and attack fungal problems.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (4, 1, 'For best results, apply as a protective spray (2.5 oz/ gallon) early in the season. If disease, insects or wet weather are present, mix 5 oz in one gallon of water. Thoroughly spray all parts of the plant, especially new shoots.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (33, 2, 'Add 1 tablespoon of captan fungicide to a gallon of water and mix it thoroughly in a hand sprayer tank. Pumping the handle, coat the branches and leaves completely. Repeat the application once every 7 to 10 days until the fruit begins to change color.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (34, 2, 'Lbs/ acre: 1-1.5. Lbs/ 100 gal: 1⁄4- 3⁄8. Apply at 5- to 10-day intervals from green tip through petal fall; continue at 7- to 14-day intervals in cover sprays. Do not apply more than 4 lbs. of product (2.8 lbs. a.i.)/A/season.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (5, 3, 'For best results, treat prior to disease development or at the first sign of disease infection. Repeat at 7-day intervals or as needed. Under conditions of high disease pressure, shorten the spray interval or, for ornamental plants, use the higher rate. Mix 1-4 oz. per gallon of water (15 oz. of spray solution treats 100 square feet).');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (3, 3, 'For best results, apply as a protective spray (2.5 oz/ gallon) early in the season. If disease, insects or wet weather are present, mix 5 oz in one gallon of water. Thoroughly spray all parts of the plant, especially new shoots.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (6, 4, '4 teaspoons/2 gal water.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (7, 4, '2 to 3 fl oz/100 gal water for home orchards or landscape use. Can be applied up to the day of harvest. Group 3 fungicide. 24-hr reentry. ');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (8, 4, '1 to 2 gal/100 gal water. Do not apply micronized sulfur within 10 days of an oil application. Do not use oil within 14 days of a sulfur application. Do not use during freezing temperatures, above 90°F, or when plants are under heat or moisture stress. Do not use when foliage is wet as good coverage is essential. Do not use past pit hardening but may be used postharvest. Excellent efficacy. 4-hr reentry.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (9, 5, 'Headline is to be applied at 400–600 mL per hectare (ha). For optimal disease control, begin applications prior to disease development (see Disease Cycle). This fungicide can only be applied a maximum of 2 applications/year. Ground and aerial application are both acceptable.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (10, 5, 'Proline 480 SC is to be applied at 420 mL per/ha. This fungicide can only be applied a maximum 1 time/year. It should be note that only ground application is acceptable. A 24-hour re-entry time is required (minimum amount of time that must pass between the time a fungicide is applied to an area or crop and the time that people can go into that area without protective clothing and equipment).');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (11, 5, 'Bumper 418 EC is to be applied at 300 mL/ha. Both fungicides are to be applied when rust pustules first appear. If disease is prevalent after primary application, a second application 14 days later may be necessary. Two weeks later, a third application can be made under severe amount of disease. Ground and aerial application are both acceptable.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (12, 5, 'Make a single 3-6 fl oz application between V4 to V7 for early season disease control/supersession. On susceptible inberds or hybrids, for early season disease control of Northern corn leaf blight, Gray leaf spot, or Common Rust, use the 6 fl oz rate. For continued control  through the season, a planned program should be followed.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (13, 5, 'Apply when disease first appears. If conditions favor disease development, reapply on a 7- to 14-day schedule. For best disease control, early applications at initial disease onset perform better. Maximum Single Application Rate: 8 fl oz (0.225 lb active ingredient) per acre. Maximum Number of Applications per Year: 2');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (12, 6, 'Make a single 3-6 fl oz application between V4 to V7 for early season disease control/supersession. On susceptible inberds or hybrids, for early season disease control of Northern corn leaf blight, Gray leaf spot, or Common Rust, use the 6 fl oz rate. For continued control  through the season, a planned program should be followed.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (13, 6, 'Apply when disease first appears. If conditions favor disease development, reapply on a 7- to 14-day schedule. For best disease control, early applications at initial disease onset perform better. Maximum Single Application Rate: 8 fl oz (0.225 lb active ingredient) per acre. Maximum Number of Applications per Year: 2');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (9, 7, 'Headline is to be applied at 400–600 mL per hectare (ha). For optimal disease control, begin applications prior to disease development (see Disease Cycle). This fungicide can only be applied a maximum of 2 applications/year. Ground and aerial application are both acceptable.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (12, 7, 'Make a single 3-6 fl oz application between V4 to V7 for early season disease control/supersession. On susceptible inberds or hybrids, for early season disease control of Northern corn leaf blight, Gray leaf spot, or Common Rust, use the 6 fl oz rate. For continued control through the season, a planned program should be followed.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (14, 8, 'Apply at 240 g/ha at a 14-day interval. Sovran is excellent for control of black rot.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (15, 8, 'Pre-bloom or prior to onset of disease on a 10 to 14 day interval. Ensure the spray tank is clean before use. Fill the tank 1/2 full of water and start agitation. Add the required amount of Pristine fungicide to the tank. Continue agitation while filling the remainder of the spray tank. After use, clean the spray tank according to label precautions.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (16, 9, 'Treatments are usually applied by spraying or painting the trunks and main branches with a sodium arsenite solution (12.5 g/liter). Treatments should be applied for 2 consecutive years, at least 2 weeks after pruning and not later than 3 weeks before sprouting (15). In the third and fourth years, the treatment can be omitted but must then be repeated in the following 2 years, and so on. The treatment threshold, i.e., percentage of affected vines in a vineyard at which intervention is required, varies from 0.5 to 2% (8).');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (15, 10, 'Max rate/acre: Application: 8-12.5 oz. Season: 69 oz. Min. days to harvest: 14.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (17, 11, 'Citrus Resets or New Plantings: Timing:  Make the first application at the time of planting. Make two or three applications per year (spring + summer, summer + fall, or spring + summer + fall). Application Method: Spray boom: Apply to soil beneath the tree canopy if rain is not expected within 24 hours after application, sprinkler irrigate with 1/2 to 1 inch of water to move product into root zone. Irrigation: Ridomil Gold SL can be applied through irrigation water (micro-sprinkler or drip) - 0.5 – 1 pt/grove acre.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (18, 11, 'Citrus (non-bearing - trees that will not produce marketable fruit for 12 months after the last ALIETTE® WDG application). Application method: Root Dip. Rate lbs product: 3.0/100 gals. Thoroughly mix ALIETTE® WDG in the desired volume of water and dip the entire root system for 30-60 minutes prior to planting in the field. Foliar. RATE lbs product: 5.0/100 gals. Begin application when conditions favor disease development. (If you are unsure about whether these conditions exist, check with your Cooperative Extension Service). Chemigation. Rate lbs product: 5.0/Acre. For foliar applications spray to wet. For chemigation inject ALIETTE® WDG continuously while applying a scheduled irrigation. Mixing ALIETTE® WDG with surfactants or foliar fertilizers is not recommended. Citrus sensitivity to a particular combination should be determined by spraying a small area of foliage and fruit. Evaluate 3-7 days later for adverse effects. Citrus (bearing). ALIETTE® WDG applied in conjunction with good cultural practices will provide effective control of foot rot, root rot, gummosis, and fruit brown rot caused by Phytophthora spp. ALIETTE® WDG also controls ice-nucleating bacteria (California only) and suppresses Alternaria Brown Spot (Florida only). Application method: Chemigation. Rate lbs product: 5.0/Acre. Begin application when conditions favor disease development. (If you are unsure about whether these conditions exist, check with your Cooperative Extension Service.) Inject ALIETTE® WDG continuously during a scheduled irrigation.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (19, 11, 'Product Application Rate: 24 oz. per acre (4.4 oz. active ingredient, ai, per acre, equivalent to 4.08 oz. oxytetracycline free base). Use Directions: Apply as a foliar spray using sufficient carrier volume to ensure complete coverage. Use with spray adjuvant, spreader sticking agent or horticultural oil. Make first application at initiation of spring flush to suppress HLB titer and disease symptoms. Make a second application midsummer (not less than 21 days after first application). Make a third application in late summer to reduce the incidence of HLB-induced fruit drop and to further suppress HLB titer and disease symptoms (not less than 21 days after second application). Specific Use Restrictions: Maximum number of applications per year: 3 Minimum retreatment interval: 21 days. Do not apply within 40 days of harvest. Maximum annual amount of product that may be applied per acre: 4.5 lbs. (0.82 lbs. active ingredient per acre, equivalent to 0.76 lbs. oxytetracycline free base) Use only the full strength application rate Follow Application Restrictions-All Uses.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (19, 12, 'Product Application Rate: 18 oz. per acre (3.29 oz. active ingredient, ai, per acre, equivalent to 3.06 oz. oxytetracycline free base). Use Directions: Begin applications at “shuck split”. When disease pressure is high, spray at 5-7-day intervals. Consider alternating or tank mixing with copper-based products. Note: certain liquid copper formulations may be incompatible with FireLine™ 17 WP Fungicide/Bactericide Agricultural Oxytetracycline. If disease pressure is low, spray interval may be lengthened accordingly. Apply product in sufficient water volume to achieve adequate coverage. Specific Use Restrictions: Maximum number of applications per year: 9 Do not apply within 21 days of harvest. Maximum annual amount that may be applied per acre: 10.125 lbs. (162 oz.) of product per acre (1.85 lbs. active ingredient per acre, equivalent to 1.72 lbs. oxytetracycline free base). Use only the full strength application rate Follow Application Restrictions-All Uses.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (20, 13, 'Application Rate/Acre: 0.75 - 1.25 lb. Maximum Annual Rate/Acre: 39.5 lb. Use Instructions: Begin applications when conditions first favor disease development and repeat at 3- to 10-day intervals if needed depending on disease severity. Use the higher rates when conditions favor disease.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (21, 13, 'Application Rate/Acre: 1.5-2.25 lbs. Maximum Seasonal Rate/Acre: 33.9 lbs. Use Instructions: Begin applications when conditions first favor disease development and repeat at 3 to 10 day intervals if needed depending on disease severity. Use the higher rates when conditions favor disease.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (22, 14, 'Product per Acre: 2.5-4.5 oz. Application Frequency (days): 7-14 days. Remarks: Max of 4 applications (20.5 oz) per season; Rotate with fungicides with a different mode of action; 30 day PHI.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (23, 14, 'Rate of equus 720 sst per application pints/acre: 0.75; then 1.0-1.5. Seasonal limits (pints/ acre/ year): 15.0. Begin applications using ground, air, or chemigation at the low rate when vines are first exposed and leaf wetness occurs. Repeat applications at 5- to 10-day intervals, but do not apply at less than 5-day intervals. Begin applying the higher label rates at 5- to 10-day intervals when any one of the following events occur: Vines close within the rows; Late blight forecasting measures 18 disease severity values (DSV); The crop reaches 300 P-days Increase water spray volume as canopy density increases. Use the highest rate and shortest interval when plants are rapidly growing and disease conditions are severe. Do not exceed a 10-day application interval when using chemigation. Do not apply within 7 days of harvest.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (24, 14, 'Rate lbs/acre: 1 – 4. Apply 1.0 - 1.5 pounds at 7 to 10 day intervals starting when plants are 6 inches high until 2 weeks before harvest in locations where disease is light and up to 3 to 4 pounds per acre where disease is more severe. Under conditions of severe disease, control with Nu-Cop 50DF will be improved by tank mixing with other compatible fungicides registered for use on potatoes. Read and follow all label instructions of tank mix partners.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (23, 15, 'Rate of equus 720 sst per application pints/acre: 0.75; then 1.0-1.5. Seasonal limits (pints/ acre/ year): 15.0. Begin applications using ground, air, or chemigation at the low rate when vines are first exposed and leaf wetness occurs. Repeat applications at 5- to 10-day intervals, but do not apply at less than 5-day intervals. Begin applying the higher label rates at 5- to 10-day intervals when any one of the following events occur: Vines close within the rows; Late blight forecasting measures 18 disease severity values (DSV). The crop reaches 300 P-days Increase water spray volume as canopy density increases. Use the highest rate and shortest interval when plants are rapidly growing and disease conditions are severe. Do not exceed a 10-day application interval when using chemigation. Do not apply within 7 days of harvest.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (24, 15, 'Rate lbs/acre: 1 – 4. Apply 1.0 - 1.5 pounds at 7 to 10 day intervals starting when plants are 6 inches high until 2 weeks before harvest in locations where disease is light and up to 3 to 4 pounds per acre where disease is more severe. Under conditions of severe disease, control with Nu-Cop 50DF will be improved by tank mixing with other compatible fungicides registered for use on potatoes. Read and follow all label instructions of tank mix partners.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (20, 16, 'Application Rate/Acre: 0.5 - 1.25 lb. Maximum Annual Rate/Acre: 17.5 lb. Use Instructions: Begin applications prior to disease development and continue while conditions are favorable for disease development. Repeat at 5- to 7-day intervals if needed. Use the higher rates when conditions favor disease. NOTE: Crop injury may occur from application at higher rates and shorter intervals. Discontinue use if injury occurs.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (21, 16, 'Application Rate/Acre: 1-2.25 lbs. Maximum Annual Rate/Acre: 15 lbs. Use Instructions: Begin applications prior to disease development and continue while conditions are favorable for disease development. Repeat at 5 to 7 day intervals if needed. Use the higher rates when conditions favor disease. NOTE: Crop injury may occur from application at higher rates and shorter intervals. Discontinue use if injury occurs.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (23, 16, 'Rate of equus 720 sst per application pints/acre: 2.0-3.0. Seasonal limits (pints/ acre/ year): 21.0. Use in sufficient water to obtain adequate coverage, applying by ground, air, or chemigation. Begin applications when plants are in first true leaf stage or when conditions are favorable for disease development. Repeat applications at 7-day intervals, but do not apply at less than 7-day intervals. Equus 720 SST may be applied the day of harvest. Note: Spraying mature watermelons may result in sunburn of the upper surface of the fruit. Do not apply Equus 720 SST to watermelons when any of the following conditions are present: Intense heat and sunlight; Drought conditions; Poor vine canopy; Other crop and environmental conditions which may be conducive to increased natural sunburn. Do not combine Equus 720 SST with anything except water for application to watermelons unless your prior use has shown the combination to be non-injurious to watermelons under your conditions of use.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (24, 16, 'Rate lbs/acre: 1.5 – 3. Begin applications when plants are 3 weeks old or when disease symptoms first appear and repeat at 7 day intervals as needed to maintain control. Use the higher rates if disease is heavy or conditions favor disease development.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (20, 17, 'Application Rate/Acre: 0.75 - 1.25 lb. Maximum Annual Rate/Acre: 27.3 lb. Use Instructions: Begin application when plants are established and continue on a weekly schedule throughout the season. Apply in at least 20 gallons of water. Use the higher rates when conditions favor disease. NOTE: Discontinue applications if signs of crop injury appear.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (21, 17, 'Application Rate/Acre: 1.5-2.25 lbs. Maximum Annual Rate/Acre: 23.4 lbs. Use Instructions: Begin application when plants are established and continue on a weekly schedule throughout the season. Apply in at least 20 gallons of water. Use the higher rates when conditions favor disease. NOTE: Discontinue applications if signs of crop injury appear.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (20, 18, 'Application Rate/Acre: 0.75 - 1.75 lb. Maximum Annual Rate/Acre: 58 lb. (processing), 26.7 lb. (fresh market). Use Instructions: Begin applications when disease first threatens and repeat at 3- to 10-day intervals if needed depending on disease severity. Use the higher rates when conditions favor disease.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (21, 18, 'Application Rate/Acre: 1.5 lbs. (processing), 1.5-3 lbs. (fresh market). Maximum Annual Rate/Acre: 49.7 lbs. (processing), 22.8 lbs. (fresh market). Use Instructions: Begin applications when disease first threatens and repeat at 3 to 10 day intervals if needed depending on disease severity. Use the higher rates when conditions favor disease.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (24, 18, 'Rate lbs/acre: 2 – 4. Begin when disease first threatens and repeat at 7 to 10 day intervals or as needed depending on disease severity. Use higher rate for severe disease.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (21, 19, 'Application Rate/Acre: 1.5 lbs. (processing), 1.5-3 lbs. (fresh market). Maximum Annual Rate/Acre: 49.7 lbs. (processing), 22.8 lbs. (fresh market). Use Instructions: Begin applications when disease first threatens and repeat at 3 to 10 day intervals if needed depending on disease severity. Use the higher rates when conditions favor disease.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (23, 19, 'Rate of equus 720 sst per application pints/acre: 1.37-2.0. Seasonal limits (pints/ acre/ year): 20.0. Use in sufficient water to obtain adequate coverage, applying by ground, air, or chemigation. Begin applications when dew or rain occurs and disease threatens. Apply every 7 to 10 days for foliage diseases. For fruit diseases, begin at fruit set and apply every 7 to 14 days. Do not apply at less than 7-day intervals. Use the highest rate and shortest interval when disease is severe. Equus 720 SST may be applied the day of harvest.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (24, 19, 'Rate lbs/acre: 2 – 3. Begin when disease first threatens and repeat at 7 to 10 day intervals or as needed depending on disease severity. Use higher rate for severe disease.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (20, 20, 'Application Rate/Acre: 0.75 - 1.75 lb. Maximum Annual Rate/Acre: 58 lb. (processing), 26.7 lb. (fresh market). Use Instructions: Begin applications when disease first threatens and repeat at 3- to 10-day intervals if needed depending on disease severity. Use the higher rates when conditions favor disease.');
