INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (26, 23, 'Abamectin (AgriMek, Syngenta Crop Protection, 8 to 16 fluid ounces per acre): Abamectin is actually a naturally derived substance and serves as a good rescue insecticide. AgriMek contains synthetic abamectin and provides long-term residual control of two-spotted spider mites.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (27, 23, 'Bifenazate (Acramite, Chemtura, 0.75 to 1 pound per acre): This is a contact poison against two-spotted spider mites with less toxicity to predaceous mites and beneficial arthropods. Acramite is a good knockdown product and also kills the eggs (ovicidal action). Do not make more than one application of bifenazate per season. The postharvest interval on tomatoes is three days.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (28, 23, 'Spiromesifen (Oberon, Bayer CropScience, 7 to 8.5 ounces per acre) This is a slow acting contact poison. Oberon, a lipid biosynthesis inhibitor in insects, may also provide some whitefly control.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (23, 24, 'Rate of equus 720 sst per application pints/acre: 1.37-2.0. Seasonal limits (pints/ acre/ year): 20.0. Use in sufficient water to obtain adequate coverage, applying by ground, air, or chemigation. Begin applications when dew or rain occurs and disease threatens. Apply every 7 to 10 days for foliage diseases. For fruit diseases, begin at fruit set and apply every 7 to 14 days. Do not apply at less than 7-day intervals. Use the highest rate and shortest interval when disease is severe. Equus 720 SST may be applied the day of harvest.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (31, 25, 'Rate Per Acre Per Application: 5 – 11.0 fl. oz./A. Maximum Platinum Allowed per Growing Season: Do not exceed a total of 11 fl. oz./Acre (0.172 lb.a.i./A) of Platinum or 0.172 lb. a.i. of thiamethoxam containing products per acre per growing season. Application Rate:  Use lower rates for short residual control and higher rates within the listed rate range for long residual control. See rate conversion chart for rate per 1,000 linear ft.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (32, 25, 'Rate fluid ounces/Acre: Okra and Pepper 7.0 – 14.0, Other Crops 7.0 – 10.5.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (29, 26, 'Apply every 7-10 days when insects are present, or as needed. Thoroughly cover all plant surfaces including the undersides of leaves. Quart (32 oz.) ready-to-use spray treats 1,000 square feet. Pint (16 oz.) concentrate (shown) makes 6 gallons of spray.');
INSERT INTO `mydb`.`DRUG_and_DISEASE` (`DRUG_drug_id`, `DISEASE_disease_id`, `instruction_description`) VALUES (30, 26, 'Apply when insect pests first arrive or as soon as damage is noticed. Spray infested plant surfaces thoroughly, including lower leaf surfaces, to point of runoff. Reapply every 7-10 days, as needed.');
